svg.script:
// Cardioid r = a(1 - sin t), cusp at the origin, y flipped for SVG, bounding box centred.
const svg = document.documentElement, a = 45, n = 240;
const cy = (-2 * a + 0.25 * a) / 2;
let d = "";
for (let i = 0; i < n; i++) {
  const t = 2 * Math.PI * i / n, r = a * (1 - Math.sin(t));
  d += (i ? "L" : "M") + (r * Math.cos(t)).toFixed(2) + "," + (-r * Math.sin(t) + cy).toFixed(2);
}
document.getElementById("shape").setAttribute("d", d + "Z");

const count = document.getElementById("count");
let likes = 0;
function toggle() {
  const on = svg.getAttribute("aria-pressed") !== "true";
  svg.setAttribute("aria-pressed", on);
  count.textContent = (likes += on ? 1 : -1);
  svg.classList.remove("pop"); void svg.getBoundingClientRect(); if (on) svg.classList.add("pop");
}
svg.addEventListener("click", toggle);
svg.addEventListener("keydown", e => { if (e.key === " " || e.key === "Enter") { e.preventDefault(); toggle(); } });
